#include <X11/Xlib.h>
#include <GL/glx.h>
#include <cairo/cairo-xlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
int main(int argc, char **argv) {
 Display *d=XOpenDisplay(NULL); if(!d)return 1;
 int s=DefaultScreen(d), gl=argc>1 && strcmp(argv[1],"gl")==0;
 XVisualInfo *v=NULL; Visual *visual=DefaultVisual(d,s); int depth=DefaultDepth(d,s);
 if(gl){int a[]={GLX_RGBA,GLX_DOUBLEBUFFER,GLX_STENCIL_SIZE,8,None}; v=glXChooseVisual(d,s,a);if(!v)return 2;visual=v->visual;depth=v->depth;}
 XSetWindowAttributes a={0};a.colormap=XCreateColormap(d,RootWindow(d,s),visual,AllocNone);a.event_mask=ExposureMask|StructureNotifyMask;
 Window w=XCreateWindow(d,RootWindow(d,s),0,0,640,480,0,depth,InputOutput,visual,CWColormap|CWEventMask,&a);
 XStoreName(d,w,gl?"Memory isolation GL":"Memory isolation Cairo");XMapWindow(d,w);XSync(d,False);
 if(gl){GLXContext c=glXCreateContext(d,v,NULL,True);glXMakeCurrent(d,w,c);glClearColor(0.1,0.1,0.1,1);glClear(GL_COLOR_BUFFER_BIT);glXSwapBuffers(d,w);glFinish();fprintf(stderr,"GL renderer: %s\n",glGetString(GL_RENDERER));}
 else {cairo_surface_t *sf=cairo_xlib_surface_create(d,w,visual,640,480);cairo_t *c=cairo_create(sf);cairo_set_source_rgb(c,0,0,0);cairo_paint(c);cairo_set_source_rgb(c,1,.5,.1);cairo_select_font_face(c,"DejaVu Sans Mono",CAIRO_FONT_SLANT_NORMAL,CAIRO_FONT_WEIGHT_NORMAL);cairo_set_font_size(c,16);cairo_move_to(c,16,40);cairo_show_text(c,"Fire Notes memory isolation");cairo_surface_flush(sf);XSync(d,False);}
 for(;;){XEvent e;XNextEvent(d,&e);}
}
